(7, 'accforepicfreegame@gmail.com', 'c1834f30ccbf578a722d415dcd1eb67f1538abef0580d0492f77714ea767548e', '2026-05-18 01:01:44', '2026-05-17 16:46:44');
INSERT INTO `product` (`Pro_Id`, `Pro_Name`, `Cat_Id`, `Brand_Id`, `Pro_Price`, `Pro_Description`, `Pro_Image`, `Pro_Size`, `Pro_Colour`, `Pro_Gender`, `Pro_Age_Group`, `Pro_Sale`, `Pro_Added_Date`, `Pro_Status`, `Vendor_Id`) VALUES
(1, 'Air Zoom Pegasus 42', 1, 1, 529.00, 'Experience a responsive ride for any run.', 'pegasus42.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Black/White', 'Unisex', 'Adult', 0, '2026-04-06', 'Available', NULL),
(2, 'Ultraboost Light', 1, 2, 899.00, 'The lightest Ultraboost ever made with epic energy.', 'ultraboost.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Blue/Red', 'Unisex', 'Adult', 0, '2026-04-06', 'Available', NULL),
(3, 'LeBron NXXT Gen', 2, 1, 749.00, 'Specifically tailored to meet the demands of the fast-paced game.', 'lebron.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Lakers Purple', 'Unisex', 'Adult', 0, '2026-04-06', 'Available', NULL),
(4, 'Nike Metcon 10', 5, 1, 629.00, 'The gold standard for training, perfect for lifting and cardio.', 'metcon10.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'White/Blue/Green', 'Unisex', 'Adult', 0, '2026-04-06', 'Available', NULL),
(5, 'Adidas Samba OG Kids', 3, 2, 459.00, 'Classic basketball-inspired sneakers for daily style.', 'sambaog.jpg', '3,3.5,4,4.5,5,5.5,6', 'Black/White', 'Unisex', 'Kids', 0, '2026-04-06', 'Available', NULL),
(6, 'Puma Velocity Nitro 4', 4, 3, 599.00, 'Advanced nitrogen-injected foam for superior cushioning.', 'velocity4.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Electric Lime', 'Unisex', 'Adult', 0, '2026-04-06', 'Available', NULL),
(7, 'Yonex Power Cushion 65Z3', 4, 4, 539.00, 'Used by top professionals for fast footwork and stability.', 'yonex_65z3.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'White/Tiger', 'Unisex', 'Adult', 0, '2026-04-06', 'Available', NULL),
(8, 'Nike Precision 7', 6, 1, 329.00, 'Create space and change direction quickly on the court.', 'precision7.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Purple/Black', 'Unisex', 'Adult', 0, '2026-04-06', 'Available', NULL),
(9, 'Nike Air Max 270', 3, 1, 659.00, 'Legendary Air gets lifted. Our first lifestyle Air Max brings you style, comfort and a whole lot of attitude.', 'airmax270.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Black/White', 'Men', 'Adult', 0, '2026-04-08', 'Available', NULL),
(10, 'Adidas Superstar', 3, 2, 429.00, 'The iconic basketball shoe from the 70s, now a lifestyle staple. Features the classic shell toe.', 'superstar.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'White/Black', 'Unisex', 'Adult', 1, '2026-04-08', 'Available', NULL),
(11, 'Puma RS-X3 Puzzle', 5, 3, 539.00, 'Extreme, exaggerated, and remixed. The RS-X3 takes the signature RS design and dials it up to the third power.', 'rsx3.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Blue', 'Men', 'Adult', 0, '2026-04-07', 'Available', NULL),
(12, 'Asics Gel-Kayano 32', 1, 7, 699.00, 'Creates a stable running experience and a more responsive feel underfoot. Perfect for long distance.', 'kayano32.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Grey/Pink/blue', 'Women', 'Adult', 1, '2026-04-09', 'Available', NULL),
(13, 'Nike Dunk Low Kids', 3, 1, 329.00, 'The classic 80s hoops shoe returns with classic details and throwback hoops flair for the little ones.', 'dunk_kids.jpg', '3,3.5,4,4.5,5,5.5,6', 'Black/Pink', 'Unisex', 'Kids', 0, '2026-04-10', 'Available', NULL),
(14, 'Under Armour Curry 10', 2, 5, 749.00, 'Change directions fast. The Curry 10 is designed for maximum court feel and responsiveness.', 'curry10.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Black', 'Men', 'Adult', 0, '2026-04-09', 'Available', NULL),
(15, 'New Balance 530', 6, 6, 459.00, 'A throwback to classic running shoe styles. The 530 combines everyday style with modern tech.', 'nb530.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'White', 'Unisex', 'Adult', 1, '2026-04-07', 'Available', NULL),
(16, 'SS Max Power', 4, 9, 829.00, 'Experience ultimate personalization. SS Max Power uses high-performance materials and supports full 3D color and material customization to create something truly unique.', 'ss_max_power.jpg', '3,3.5,4,4.5,5,5.5,6,6.5,7,7.5,8,8.5,9,9.5,10,10.5,11', 'Default', 'Unisex', 'Adult', 0, '2026-04-24', 'Available', NULL),
(33, 'Converse AS-1 Pro', 5, 8, 509.00, 'Engineered for peak performance and unwavering comfort, the Converse AS-1 Pro offers a sleek, modern style that keeps you on your game. Experience superior cushioning and responsive support designed to elevate your training sessions and conquer your goals with confidence.', 'converseas-1pro.webp', '4.0,4.5,5.0,5.5,6.0,6.5,7.0,7.5,8.0,8.5,9.0,9.5,10.0', 'Blue,Brown', 'Men', 'Adult', 0, '2026-06-22', 'Available', NULL),
(34, 'Converse Chuck Taylor Throwback Low ', 3, 8, 399.00, 'Step back in time with the Converse Chuck Taylor Throwback Low, where iconic style meets all-day comfort and dependable performance for the modern woman. These timeless lifestyle sneakers offer a classic aesthetic designed for effortless wear, keeping you looking and feeling great no matter where your day takes you.', 'conversechucktaylorthrowbacklow.webp', '5.0,5.5,6.0,6.5,7.0,7.5,8.0,8.5,9.0,9.5,10.0,10.5', 'Black', 'Women', 'Adult', 0, '2026-06-22', 'Available', NULL),
(35, 'Converse All Star Ox Junior', 3, 8, 1.03, 'Lace up iconic style and all-day comfort with the Converse All Star Ox Junior, designed for active kids who demand performance and trendsetting looks. These versatile lifestyle sneakers deliver durable support and a classic aesthetic, making them the perfect choice for everyday adventures and playground fun.', 'converseallstaroxjunior.webp', '3.0,3.5,4.0,4.5,5.0,5.5,6.0', 'White', 'Unisex', 'Kids', 0, '2026-06-22', 'Available', NULL);
